import React, { useState, useEffect } from 'react';
import { loadStripe } from '@stripe/stripe-js';
import { Elements, CardElement, useStripe, useElements } from '@stripe/react-stripe-js';
import api from '../utils/api';
import { useAuth } from '../context/AuthContext';
import {
  ArrowDownLeft,
  CreditCard,
  AlertCircle,
  CheckCircle,
  Loader2,
  Shield
} from 'lucide-react';
import toast from 'react-hot-toast';

const stripePromise = loadStripe(process.env.REACT_APP_STRIPE_KEY || 'pk_test_placeholder');

const DepositForm = () => {
  const stripe = useStripe();
  const elements = useElements();
  const { user } = useAuth();
  const [amount, setAmount] = useState('');
  const [clientSecret, setClientSecret] = useState('');
  const [loading, setLoading] = useState(false);
  const [step, setStep] = useState(1);
  const [errors, setErrors] = useState({});

  const validate = () => {
    const newErrors = {};
    if (!amount || parseFloat(amount) < 1) newErrors.amount = 'Minimum deposit is $1';
    setErrors(newErrors);
    return Object.keys(newErrors).length === 0;
  };

  const handleCreateIntent = async () => {
    if (!validate()) return;
    setLoading(true);
    try {
      const res = await api.post('/payments/create-payment-intent', {
        amount: parseFloat(amount),
        currency: 'usd'
      });
      setClientSecret(res.data.clientSecret);
      setStep(2);
    } catch (error) {
      toast.error(error.response?.data?.message || 'Failed to initialize payment');
    } finally {
      setLoading(false);
    }
  };

  const handleSubmit = async (e) => {
    e.preventDefault();
    if (!stripe || !elements) return;

    setLoading(true);
    try {
      const { error, paymentIntent } = await stripe.confirmCardPayment(clientSecret, {
        payment_method: {
          card: elements.getElement(CardElement),
          billing_details: {
            name: `${user?.firstName} ${user?.lastName}`,
            email: user?.email,
            phone: user?.phone
          }
        }
      });

      if (error) {
        toast.error(error.message);
      } else if (paymentIntent.status === 'succeeded') {
        toast.success('Deposit successful! Your balance has been updated.');
        setStep(3);
      } else {
        toast.info('Payment processing. You will be notified when complete.');
      }
    } catch (err) {
      toast.error('Payment failed. Please try again.');
    } finally {
      setLoading(false);
    }
  };

  const cardElementOptions = {
    style: {
      base: {
        color: '#f1f5f9',
        fontSize: '16px',
        fontFamily: 'Inter, sans-serif',
        '::placeholder': { color: '#64748b' },
      },
      invalid: {
        color: '#ef4444',
        iconColor: '#ef4444'
      }
    }
  };

  return (
    <div className="space-y-6">
      {step === 1 && (
        <>
          <div>
            <label className="block text-sm font-medium text-dark-300 mb-2">Amount (USD)</label>
            <div className="relative">
              <span className="absolute left-4 top-1/2 -translate-y-1/2 text-dark-400 font-medium">$</span>
              <input
                type="number"
                value={amount}
                onChange={(e) => setAmount(e.target.value)}
                className={`input-field pl-10 ${errors.amount ? 'border-red-500' : ''}`}
                placeholder="0.00"
                min="1"
                step="0.01"
              />
            </div>
            {errors.amount && (
              <p className="mt-1 text-sm text-red-400 flex items-center gap-1">
                <AlertCircle className="w-4 h-4" /> {errors.amount}
              </p>
            )}
          </div>

          <div className="p-4 rounded-xl bg-dark-950 border border-dark-700">
            <div className="flex items-center gap-2 mb-2">
              <Shield className="w-4 h-4 text-primary-400" />
              <span className="text-sm font-medium text-dark-300">Secure Payment</span>
            </div>
            <p className="text-sm text-dark-500">
              Your card details are encrypted and processed securely by Stripe. We never store your card information.
            </p>
          </div>

          <button
            onClick={handleCreateIntent}
            disabled={loading}
            className="w-full btn-primary flex items-center justify-center gap-2 disabled:opacity-50"
          >
            {loading ? (
              <Loader2 className="w-5 h-5 animate-spin" />
            ) : (
              <>Continue to Payment <ArrowDownLeft className="w-5 h-5" /></>
            )}
          </button>
        </>
      )}

      {step === 2 && (
        <form onSubmit={handleSubmit} className="space-y-6">
          <div className="p-4 rounded-xl bg-dark-950 border border-dark-700">
            <div className="flex justify-between mb-3">
              <span className="text-dark-400">Amount</span>
              <span className="text-white font-bold">${parseFloat(amount).toFixed(2)}</span>
            </div>
            <div className="flex justify-between">
              <span className="text-dark-400">Fee</span>
              <span className="text-emerald-400 font-medium">$0.00</span>
            </div>
          </div>

          <div>
            <label className="block text-sm font-medium text-dark-300 mb-2">Card Details</label>
            <div className="p-4 rounded-xl bg-dark-950 border border-dark-700">
              <CardElement options={cardElementOptions} />
            </div>
          </div>

          <div className="flex gap-3">
            <button
              type="button"
              onClick={() => setStep(1)}
              className="flex-1 btn-secondary"
            >
              Back
            </button>
            <button
              type="submit"
              disabled={!stripe || loading}
              className="flex-1 btn-primary flex items-center justify-center gap-2 disabled:opacity-50"
            >
              {loading ? (
                <Loader2 className="w-5 h-5 animate-spin" />
              ) : (
                <>Pay ${parseFloat(amount).toFixed(2)} <CreditCard className="w-5 h-5" /></>
              )}
            </button>
          </div>
        </form>
      )}

      {step === 3 && (
        <div className="text-center space-y-6">
          <div className="w-20 h-20 rounded-full bg-emerald-600/20 flex items-center justify-center mx-auto">
            <CheckCircle className="w-10 h-10 text-emerald-400" />
          </div>
          <div>
            <h2 className="text-2xl font-bold text-white mb-2">Deposit Successful!</h2>
            <p className="text-dark-400">
              ${parseFloat(amount).toFixed(2)} has been added to your wallet.
            </p>
          </div>
          <button
            onClick={() => { setStep(1); setAmount(''); setClientSecret(''); }}
            className="btn-primary"
          >
            Make Another Deposit
          </button>
        </div>
      )}
    </div>
  );
};

const Deposit = () => {
  const [stripeKey, setStripeKey] = useState('');

  useEffect(() => {
    const fetchConfig = async () => {
      try {
        const res = await api.get('/payments/config');
        setStripeKey(res.data.publishableKey);
      } catch (error) {
        console.error('Failed to load Stripe config');
      }
    };
    fetchConfig();
  }, []);

  return (
    <div className="w-full max-w-2xl mx-auto px-4 animate-fade-in">
      <div className="mb-8">
        <h1 className="text-3xl font-bold text-white">Deposit Funds</h1>
        <p className="text-dark-400 mt-1">Add money to your wallet securely</p>
      </div>

      <div className="card">
        <Elements stripe={stripePromise}>
          <DepositForm />
        </Elements>
      </div>

      <div className="mt-6 p-4 rounded-xl bg-dark-950/50 border border-dark-700/50">
        <h3 className="font-medium text-white mb-2">Supported Methods</h3>
        <div className="flex flex-wrap gap-3">
          {['Visa', 'Mastercard', 'American Express', 'Discover'].map((card) => (
            <span key={card} className="px-3 py-1 rounded-lg bg-dark-800 text-dark-400 text-sm">
              {card}
            </span>
          ))}
        </div>
      </div>
    </div>
  );
};

export default Deposit;
